(() => {
  "use strict";

  // Everything course-specific lives in deck.js (window.DECK), generated by build_app.py.
  const D = window.DECK;
  const CARDS = D.cards;
  const TOPICS = D.topics;                       // [{ id, name, short }]
  const INTERVALS = D.settings.intervals;        // days per box, e.g. [1, 2, 4, 7, 12]
  const NBOX = INTERVALS.length;
  const BOXES = Array.from({ length: NBOX }, (_, i) => i + 1);
  const ON_WRONG = D.settings.onWrong;           // "back-one" | "first-box"
  const EXAM = D.course.examDate || null;        // "YYYY-MM-DD" or null
  const STORE = D.course.storageKey;
  const TOPIC_SHORT = Object.fromEntries(TOPICS.map(t => [t.id, t.short || t.id]));

  const BY_ID = Object.fromEntries(CARDS.map(c => [c.id, c]));
  const $app = document.getElementById("app");

  // ── Dates (local calendar days, "YYYY-MM-DD") ─────────────────────
  const pad = n => String(n).padStart(2, "0");
  const fmt = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const parse = s => { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); };
  const addDays = (s, n) => { const d = parse(s); d.setDate(d.getDate() + n); return fmt(d); };
  const diffDays = (a, b) => Math.round((parse(b) - parse(a)) / 86400000);
  const testDay = new URLSearchParams(location.search).get("today"); // ?today=YYYY-MM-DD for testing
  const today = () => (testDay && /^\d{4}-\d{2}-\d{2}$/.test(testDay) ? testDay : fmt(new Date()));
  const niceDate = s => parse(s).toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" });
  const boxLabel = b => (INTERVALS[b - 1] === 1 ? "daily" : `${INTERVALS[b - 1]} days`);

  // ── Persistence ───────────────────────────────────────────────────
  function load() {
    try {
      const raw = localStorage.getItem(STORE);
      if (raw) {
        const s = JSON.parse(raw);
        return { cards: s.cards || {}, log: s.log || {}, filter: s.filter || "all" };
      }
    } catch (e) { /* storage unavailable: run in memory */ }
    return { cards: {}, log: {}, filter: "all" };
  }
  function save() {
    try { localStorage.setItem(STORE, JSON.stringify(state)); } catch (e) { /* ignore */ }
  }
  let state = load();
  if (state.filter !== "all" && !TOPICS.some(t => t.id === state.filter)) state.filter = "all";

  const cs = id => {
    const s = state.cards[id] || { box: 1, due: null, r: 0, w: 0 };
    return s.box > NBOX ? { ...s, box: NBOX } : s;
  };
  const isDue = id => { const s = cs(id); return !s.due || s.due <= today(); };
  const inFilter = (c, f = state.filter) => f === "all" || c.topics.includes(f);
  const filtered = f => CARDS.filter(c => inFilter(c, f));

  // ── Leitner move ──────────────────────────────────────────────────
  function grade(id, correct) {
    const s = { ...cs(id) };
    const t = today();
    if (correct) {
      s.box = Math.min(NBOX, s.box + 1);
      s.r++;
      s.due = addDays(t, INTERVALS[s.box - 1]);
    } else {
      s.box = ON_WRONG === "first-box" ? 1 : Math.max(1, s.box - 1);
      s.w++;
      s.due = addDays(t, 1);
    }
    // Fit to the exam: nothing is scheduled later than the day before it.
    if (EXAM) {
      const eve = addDays(EXAM, -1);
      if (t < eve && s.due > eve) s.due = eve;
    }
    state.cards[id] = s;
    state.log[t] = (state.log[t] || 0) + 1;
    save();
    return s.box;
  }

  function streak() {
    let n = 0, d = today();
    if (!state.log[d]) d = addDays(d, -1); // not studied yet today doesn't break it
    while (state.log[d]) { n++; d = addDays(d, -1); }
    return n;
  }

  // ── Helpers ───────────────────────────────────────────────────────
  const esc = s => String(s).replace(/[&<>"]/g, ch => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[ch]));
  const shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  // Red (box 1) → green (last box).
  const boxColor = b => `hsl(${Math.round(4 + ((b - 1) / Math.max(1, NBOX - 1)) * 142)} 55% 50%)`;
  const topicTag = c => c.topics.map(t => TOPIC_SHORT[t] || t).join(" · ");
  const plural = (n, w) => `${n} ${w}${n === 1 ? "" : "s"}`;
  // Formulas: when the deck turns math on, index.html loads KaTeX. Delimiters are \( \) and $$ $$
  // only — never single $, because course text is full of prices like $1.20.
  function typeset() {
    if (!window.renderMathInElement) return;
    try {
      window.renderMathInElement($app, {
        delimiters: [{ left: "$$", right: "$$", display: true }, { left: "\\(", right: "\\)", display: false }],
        throwOnError: false,
      });
    } catch (e) { /* leave raw text */ }
  }
  window.addEventListener("load", () => typeset());
  const icon = {
    close: '<svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18"/></svg>',
    undo: '<svg viewBox="0 0 24 24"><path d="M9 14L4 9l5-5"/><path d="M4 9h10a6 6 0 010 12h-3"/></svg>',
  };

  // ── Home ──────────────────────────────────────────────────────────
  function home() {
    session = null;
    const t = today();
    const list = filtered();
    const due = list.filter(c => isDue(c.id));
    const counts = Array(NBOX + 1).fill(0);
    list.forEach(c => counts[cs(c.id).box]++);
    const max = Math.max(1, ...counts.slice(1));
    const strongFrom = Math.max(2, NBOX - 1);
    const strong = CARDS.filter(c => cs(c.id).box >= strongFrom).length;
    const pct = Math.round((strong / CARDS.length) * 100);
    const C = 2 * Math.PI * 26;
    const selTopic = TOPICS.find(x => x.id === state.filter);

    let next = "";
    if (!due.length) {
      const dates = list.map(c => cs(c.id).due).filter(Boolean).sort();
      if (dates.length) {
        const d = dates[0];
        const n = list.filter(c => cs(c.id).due === d).length;
        next = `Next: ${plural(n, "card")} ${diffDays(t, d) === 1 ? "tomorrow" : "on " + niceDate(d)}`;
      }
    }

    let countdown;
    if (!EXAM) {
      countdown = `<div class="days">${CARDS.length}<small>cards</small></div><div class="exam">${esc(D.course.subtitle || "No exam date set")}</div>`;
    } else {
      const left = diffDays(t, EXAM);
      countdown = (left > 0
        ? `<div class="days">${left}<small>${left === 1 ? "day" : "days"} to go</small></div>`
        : left === 0
          ? `<div class="days">Today<small>good luck</small></div>`
          : `<div class="days">Done<small>exam was ${-left}d ago</small></div>`)
        + `<div class="exam">${esc(D.course.examLabel || "Exam")} · ${niceDate(EXAM)}</div>`;
    }

    const topicRow = (key, num, name) => {
      const cards = filtered(key);
      const d = cards.filter(c => isDue(c.id)).length;
      const seg = BOXES.map(b => {
        const n = cards.filter(c => cs(c.id).box === b && cs(c.id).due).length;
        return n ? `<i style="width:${(n / cards.length) * 100}%;background:${boxColor(b)}"></i>` : "";
      }).join("");
      return `<button class="topic ${state.filter === key ? "sel" : ""}" data-filter="${esc(key)}" aria-pressed="${state.filter === key}">
        <span class="name">${num ? `<em>${esc(num)}</em>` : ""}${esc(name)}</span>
        <span class="due ${d ? "has" : ""}">${d ? `${d} due` : "✓ done"}</span>
        <span class="mini">${seg}</span>
      </button>`;
    };

    $app.innerHTML = `
      <header class="topbar">
        <h1>${esc(D.course.title)}</h1>
        <span class="sub">${plural(CARDS.length, "card")}</span>
      </header>

      <section class="hero">
        ${countdown}
        <svg class="ring" width="64" height="64" viewBox="0 0 64 64" role="img" aria-label="${pct}% of cards in the top boxes">
          <circle cx="32" cy="32" r="26" fill="none" stroke="var(--surface-2)" stroke-width="7"/>
          ${pct ? `<circle cx="32" cy="32" r="26" fill="none" stroke="${boxColor(NBOX)}" stroke-width="7" stroke-linecap="round"
            stroke-dasharray="${(pct / 100) * C} ${C}" transform="rotate(-90 32 32)"/>` : ""}
          <text x="32" y="36" text-anchor="middle" font-size="14" font-weight="700" fill="var(--text)">${pct}%</text>
        </svg>
      </section>

      <div class="stats">
        <div class="stat"><b>${CARDS.filter(c => isDue(c.id)).length}</b><span>due today</span></div>
        <div class="stat"><b>${state.log[t] || 0}</b><span>done today</span></div>
        <div class="stat"><b>${streak()}</b><span>day streak</span></div>
      </div>

      <h2 class="section">Boxes${selTopic ? " · " + esc(selTopic.short || selTopic.id) : ""}</h2>
      <div class="boxes" style="grid-template-columns:repeat(${NBOX},1fr)">
        ${BOXES.map(b => `
          <div class="box">
            <div class="bar"><div class="fill" style="height:${(counts[b] / max) * 100}%;background:${boxColor(b)}"></div></div>
            <div class="n">${counts[b]}</div>
            <div class="lbl">Box ${b}<br>${boxLabel(b)}</div>
          </div>`).join("")}
      </div>

      ${TOPICS.length > 1 ? `<h2 class="section">Topics</h2>
      <div class="topics">
        ${topicRow("all", "", "All topics")}
        ${TOPICS.map(x => topicRow(x.id, x.number || "", x.name)).join("")}
      </div>` : ""}

      <details class="how">
        <summary>How it works</summary>
        <p>Every card starts in Box 1. Get it right and it moves up a box, so you see it less often (Box 1 ${boxLabel(1)} → Box ${NBOX} every ${INTERVALS[NBOX - 1]} days). Get it wrong and it ${ON_WRONG === "first-box" ? "goes back to Box 1" : "drops one box"} and comes back tomorrow, plus once more at the end of the session.</p>
        ${EXAM ? `<p>Nothing is scheduled after ${niceDate(addDays(EXAM, -1))}, so every card comes back before the exam.</p>` : ""}
        <p>Open questions: answer in your head, reveal, then rate yourself honestly. MCQs are graded automatically.</p>
        <p>Progress is saved on this device only.</p>
        <button class="link-btn" data-act="reset">Reset all progress</button>
      </details>

      <div class="dock"><div class="dock-inner">
        <button class="btn primary" data-act="start" ${due.length ? "" : "disabled"}>
          ${due.length ? `Review ${plural(due.length, "card")}` : selTopic ? `${esc(selTopic.short || selTopic.id)} done for today` : "All caught up"}
        </button>
      </div>${next ? `<div class="dock-note">${next}</div>` : ""}</div>
    `;
    typeset();
  }

  // ── Study session ─────────────────────────────────────────────────
  let session = null;

  function start() {
    const due = filtered().filter(c => isDue(c.id));
    if (!due.length) return;
    const byBox = {};
    due.forEach(c => (byBox[cs(c.id).box] ||= []).push(c.id));
    const order = BOXES.flatMap(b => shuffle(byBox[b] || []));
    session = {
      queue: order.map(id => ({ id, retry: false })),
      i: 0, firstTotal: order.length, right: 0, wrong: 0, up: 0, down: 0,
      revealed: false, picked: null, undo: [],
    };
    window.scrollTo(0, 0);
    study();
  }

  function current() {
    const item = session.queue[session.i];
    const card = BY_ID[item.id];
    if (card.type === "mcq" && !item.order) item.order = shuffle(card.options.map((_, k) => k));
    return { item, card };
  }

  function snapshot() {
    session.undo.push(JSON.stringify({
      cards: state.cards, log: state.log,
      s: { ...session, undo: undefined, queue: session.queue.map(q => ({ ...q })) },
    }));
    if (session.undo.length > 30) session.undo.shift();
  }

  function undo() {
    const raw = session.undo.pop();
    if (!raw) return;
    const snap = JSON.parse(raw);
    state.cards = snap.cards; state.log = snap.log; save();
    const stack = session.undo;
    session = { ...snap.s, undo: stack, revealed: false, picked: null };
    study();
  }

  function answer(correct) {
    const { item } = current();
    snapshot();
    if (!item.retry) {
      const before = cs(item.id).box;
      const after = grade(item.id, correct);
      if (correct) session.right++; else session.wrong++;
      if (after > before) session.up++;
      if (after < before) session.down++;
    }
    if (!correct) session.queue.push({ id: item.id, retry: true });
  }

  function advance() {
    session.i++;
    session.revealed = false;
    session.picked = null;
    window.scrollTo(0, 0);
    if (session.i >= session.queue.length) summary(); else study();
  }

  function study() {
    const { item, card } = current();
    const box = cs(item.id).box;
    const pos = Math.min(session.i + 1, session.queue.length);
    const total = session.queue.length;
    const upBox = Math.min(NBOX, box + 1);
    const downBox = ON_WRONG === "first-box" ? 1 : Math.max(1, box - 1);
    const repeats = total - session.firstTotal;

    let body = "", dock = "";
    if (card.type === "mcq") {
      const picked = session.picked;
      const done = picked !== null;
      body = `<div class="opts">${item.order.map((k, p) => {
        let cls = "opt";
        if (done) cls += k === card.correct ? " right" : k === picked ? " wrong" : " dim";
        return `<button class="${cls}" data-pick="${k}" ${done ? "disabled" : ""}>
          <span class="k">${"ABCDEFGH"[p]}</span><span>${esc(card.options[k])}</span></button>`;
      }).join("")}</div>`;
      if (done) {
        const ok = picked === card.correct;
        const move = item.retry ? "" : ` · now in Box ${box}`;
        body += `<div class="verdict ${ok ? "ok" : "no"}"><strong>${ok ? "Correct" : "Not quite"}${move}</strong>${card.explain ? esc(card.explain) : ""}</div>`;
        dock = `<button class="btn primary" data-act="next">Continue</button>`;
      } else {
        dock = `<div class="dock-note" style="flex:1;margin:0;padding:18px 0">Tap an option</div>`;
      }
    } else {
      if (session.revealed) {
        body = `<div class="answer"><div class="answer-lbl">${esc(D.course.answerLabel || "Model answer")}</div>${card.a}</div>`;
        dock = item.retry
          ? `<button class="btn bad" data-rate="0">Still shaky</button><button class="btn good" data-rate="1">Got it</button>`
          : `<button class="btn bad" data-rate="0">Missed it <small>→ Box ${downBox}</small></button>
             <button class="btn good" data-rate="1">Got it <small>→ Box ${upBox}</small></button>`;
      } else {
        dock = `<button class="btn primary" data-act="reveal">Show answer</button>`;
      }
    }

    $app.innerHTML = `
      <div class="study-top">
        <button class="icon-btn" data-act="home" aria-label="End session">${icon.close}</button>
        <div class="progress">
          <div class="track"><i style="width:${(session.i / total) * 100}%"></i></div>
          <div class="count">${pos} / ${total}${repeats > 0 ? ` · ${plural(repeats, "repeat")}` : ""}</div>
        </div>
        <button class="icon-btn" data-act="undo" aria-label="Undo last answer" ${session.undo.length ? "" : "disabled"}>${icon.undo}</button>
      </div>
      <article class="card${!session.revealed && session.picked === null ? " enter" : ""}">
        <div class="meta">
          <span class="pill box" style="background:${boxColor(box)}">Box ${box}</span>
          <span class="pill">${esc(topicTag(card))}</span>
          <span class="pill">${card.type === "mcq" ? "MCQ" : esc(card.src || "Open")}</span>
          ${item.retry ? `<span class="pill again">Again</span>` : ""}
        </div>
        <h2 class="q">${card.qHtml ? card.q : esc(card.q)}</h2>
        ${body}
      </article>
      <div class="dock"><div class="dock-inner">${dock}</div></div>
    `;
    typeset();
  }

  function summary() {
    const n = session.right + session.wrong;
    const pct = n ? Math.round((session.right / n) * 100) : 0;
    const emoji = pct >= 85 ? "🎯" : pct >= 60 ? "💪" : "📚";
    $app.innerHTML = `
      <div class="done">
        <div class="big">${emoji}</div>
        <h2>Session complete</h2>
        <p>${plural(n, "card")} reviewed · ${pct}% first try</p>
        <div class="score">
          <div class="stat ok"><b>${session.right}</b><span>correct · ${session.up} moved up</span></div>
          <div class="stat no"><b>${session.wrong}</b><span>missed · ${session.down} moved down</span></div>
        </div>
      </div>
      <div class="dock"><div class="dock-inner"><button class="btn primary" data-act="home">Done</button></div></div>
    `;
    session = null;
  }

  // ── Events ────────────────────────────────────────────────────────
  $app.addEventListener("click", e => {
    const el = e.target.closest("button");
    if (!el || el.disabled) return;
    const act = el.dataset.act;
    if (el.dataset.filter) { state.filter = el.dataset.filter; save(); home(); return; }
    if (act === "start") return start();
    if (act === "home") return home();
    if (act === "reset") {
      if (confirm("Reset all progress? Every card goes back to Box 1. This can't be undone.")) {
        state = { cards: {}, log: {}, filter: "all" }; save(); home();
      }
      return;
    }
    if (!session) return;
    if (act === "undo") return undo();
    if (act === "reveal") { session.revealed = true; study(); return; }
    if (act === "next") return advance();
    if (el.dataset.rate !== undefined) { answer(el.dataset.rate === "1"); advance(); return; }
    if (el.dataset.pick !== undefined) {
      const k = Number(el.dataset.pick);
      const { card } = current();
      answer(k === card.correct);
      session.picked = k;
      study();
    }
  });

  // Keyboard (desktop): space/enter = reveal/continue, 1 = missed, 2 = got it, a–h = pick.
  document.addEventListener("keydown", e => {
    if (!session) return;
    const click = sel => { const b = $app.querySelector(sel); if (b && !b.disabled) b.click(); };
    if (e.key === " " || e.key === "Enter") { e.preventDefault(); click('[data-act="reveal"],[data-act="next"]'); }
    else if (e.key === "1") click('[data-rate="0"]');
    else if (e.key === "2") click('[data-rate="1"]');
    else if (/^[a-h]$/i.test(e.key)) { const b = $app.querySelectorAll(".opt")["abcdefgh".indexOf(e.key.toLowerCase())]; if (b && !b.disabled) b.click(); }
  });

  // Refresh the home screen when the app comes back (e.g. the next day).
  document.addEventListener("visibilitychange", () => { if (!document.hidden && !session) home(); });

  if ("serviceWorker" in navigator && location.protocol.startsWith("http")) {
    navigator.serviceWorker.register("sw.js").catch(() => {});
  }

  home();
})();
